/**
 * EQUITY_BY_TOP_PERCENT[p] is the equity a hand needs in order to sit inside the strongest p% of
 * all 1326 possible holdings, weighted by how often each is actually dealt.
 *
 * This is what makes a VPIP figure mean something. A bot configured to play 28% of hands should
 * play the hands that really are the top 28% of the deck, and the old code compared a heuristic
 * strength against 1 - vpip/100 as though that number lived on the same scale, which it did not.
 */
const EQUITY_BY_TOP_PERCENT = [1,0.7995,0.7499,0.6926,0.6609,0.6549,0.6404,0.6347,0.629,0.6289,0.6181,0.6137,0.612,0.606,0.6,0.5977,0.5976,0.5915,0.5897,0.5808,0.5786,0.5784,0.5751,0.5745,0.5739,0.5695,0.5628,0.5586,0.5578,0.5571,0.5552,0.5516,0.5489,0.5483,0.5433,0.5398,0.5365,0.5327,0.5323,0.5272,0.5219,0.5214,0.5154,0.5147,0.5134,0.511,0.5088,0.5084,0.5054,0.5008,0.4985,0.496,0.4934,0.4902,0.4847,0.4823,0.4806,0.4776,0.4754,0.4698,0.4672,0.4651,0.4631,0.4578,0.4529,0.4526,0.4501,0.4453,0.4437,0.4416,0.4379,0.4358,0.4331,0.4264,0.4242,0.424,0.4218,0.4153,0.4101,0.4057,0.4053,0.4022,0.4,0.3984,0.3958,0.3885,0.3881,0.3826,0.3804,0.3774,0.3728,0.3665,0.3642,0.3623,0.3616,0.3525,0.3445,0.3422,0.3399,0.3307,0.3239];

/** Equity floor for playing the strongest pct percent of hands. Accepts fractional percents. */
function equityForTopPercent(pct) {
  const p = Math.max(0, Math.min(100, Number(pct) || 0));
  const lo = Math.floor(p);
  const hi = Math.min(100, lo + 1);
  const t = p - lo;
  return EQUITY_BY_TOP_PERCENT[lo] * (1 - t) + EQUITY_BY_TOP_PERCENT[hi] * t;
}

/** Canonical key for two cards, e.g. 'AKs'. */
function canonicalKey(card1, card2, RANKS) {
  const a = RANKS.indexOf(card1.rank);
  const b = RANKS.indexOf(card2.rank);
  const hi = a >= b ? a : b;
  const lo = a >= b ? b : a;
  if (hi === lo) return RANKS[hi] + RANKS[hi];
  return RANKS[hi] + RANKS[lo] + (card1.suit === card2.suit ? 's' : 'o');
}

module.exports = { PREFLOP_EQUITY, EQUITY_BY_TOP_PERCENT, canonicalKey, equityForTopPercent };
